// Never trust an external call's output shape without checking it.
const upstream = $('Load Classifier Prompt (full text)').item.json;

let parsed;

try {
  const text = $json.content?.[0]?.text ?? '';
  parsed = JSON.parse(text);
} catch (e) {
  return {
    json: {
      ...upstream,
      error_state: 'MALFORMED_OUTPUT',
      processing_method: 'LLM'
    }
  };
}

const validIntents = [
  'CONFIRMED',
  'RESCHEDULE',
  'CANCEL_CHANGE',
  'QUESTION',
  'AMBIGUOUS'
];

if (
  !parsed.intent ||
  !validIntents.includes(parsed.intent) ||
  typeof parsed.confidence !== 'number' ||
  parsed.confidence < 0 ||
  parsed.confidence > 1
) {
  return {
    json: {
      ...upstream,
      error_state: 'UNSUPPORTED_INTENT',
      processing_method: 'LLM'
    }
  };
}

return {
  json: {
    ...upstream,
    detected_intent: parsed.intent,
    confidence: parsed.confidence,
    classifier_summary:
      typeof parsed.summary === 'string'
        ? parsed.summary
        : '',
    processing_method: 'LLM'
  }
};

return {
  json: {
    ...$json,
    final_status: 'CONFIRMED',
    linda_action_required: false,
    suggested_action: null
  }
};

return {
  json: {
    ...$json,
    final_status: 'NO_RESPONSE',
    linda_action_required: true,
    suggested_action: 'Call customer'
  }
};

const acks = {
  CONFIRMED: "Thanks, you're confirmed. We'll see you tomorrow.",
  NEEDS_RESCHEDULE: "Thanks. I've passed your request to our dispatch team. They'll follow up to confirm any schedule change.",
  NEEDS_RESPONSE: "Thanks. I've passed your question to our team and they'll follow up.",
  NEEDS_REVIEW: "Thanks. I've passed your message to our team and they'll follow up shortly."
};

return {
  json: {
    ...$json,
    customer_acknowledgement: acks[$json.final_status] || null
  }
};

if ($json.customer_acknowledgement) {
  console.log(
    'SIMULATED SMS ACK ->',
    $json.phone,
    ':',
    $json.customer_acknowledgement
  );
}

return {
  json: {
    ...$json,
    acknowledgement_sent: Boolean($json.customer_acknowledgement)
  }
};

const store = $getWorkflowStaticData('global');

store.audit = store.audit || [];
store.audit.push($json);

return {
  json: {
    ...$json
  }
};

const intent = $json.detected_intent;
const confidence = $json.confidence;
const errorState = $json.error_state;

let final_status;
let linda_action_required = false;
let suggested_action = null;
let escalation_reason = null;

if (errorState) {
  final_status = 'NEEDS_REVIEW';
  linda_action_required = true;
  suggested_action = 'Review response manually';
  escalation_reason = `LLM failure: ${errorState}`;
}

else if (intent === 'CONFIRMED' && confidence >= 0.85) {
  final_status = 'CONFIRMED';
}

else if (intent === 'CONFIRMED') {
  final_status = 'NEEDS_REVIEW';
  linda_action_required = true;
  suggested_action = 'Review response manually';
  escalation_reason =
    `Low-confidence CONFIRMED (${confidence}) below 0.85 threshold`;
}

else if (intent === 'RESCHEDULE') {
  final_status = 'NEEDS_RESCHEDULE';
  linda_action_required = true;
  suggested_action =
    'Contact customer to review requested schedule change';
}

else if (intent === 'CANCEL_CHANGE') {
  final_status = 'NEEDS_REVIEW';
  linda_action_required = true;
  suggested_action =
    'Review cancellation/change request before updating ServiceTitan';
}

else if (intent === 'QUESTION') {
  final_status = 'NEEDS_RESPONSE';
  linda_action_required = true;
  suggested_action = 'Respond to customer question';
}

else {
  final_status = 'NEEDS_REVIEW';
  linda_action_required = true;
  suggested_action = 'Review ambiguous customer response';
}

return {
  json: {
    ...$json,
    final_status,
    linda_action_required,
    suggested_action,
    escalation_reason
  }
};
